  const INS = { rate: 0.0015, min: 3000, max: 2000000000, deductible: 0.5, claimDays: 30, policy: 'GP-2026-0001 (SAMPLE)', bin: '990440000017', from: '2026-01-01', to: '2026-12-31', kind: T('генеральный полис на грузы (open cover)', 'Generalpolice für Waren (Open Cover)', 'open cargo cover', 'жүктерге бас полис (open cover)'), insurer: T('Страховая компания (по договору, планируется)', 'Versicherer (Vertrag geplant)', 'Insurance company (to be contracted)', 'Сақтандыру компаниясы (жоспарлануда)') };
  globalThis.INS_POLICY = INS;
  const nf = n => LF.int(n || 0);
