    const p = priceFor({ from: b.from, to: b.to, zone: b.zone, pallets: b.pallets || 1, kg: b.kg || 0, cust: b.cust, insured: b.insured, declared: b.value || b.declared || 0, express: b.express, dg: b.dg || null });
    return { base: p.freight, express: p.express, ins: p.premium, net: p.net, vat: p.vat, total: b.gross || p.gross, p };
