    if (!noteOk(note, 3)) return T('Комментарий проверки (мин. 3 символа)', 'Prüfvermerk (mind. 3 Zeichen)', 'Check note (min. 3 characters)', 'Тексеру пікірі (кемінде 3 таңба)');
    if (b.src !== 'portal' && b.by && b.by === S.role) return T('Автор заявки не может проверять адрес', 'Der Antragsteller darf die Adresse nicht prüfen', 'The requester may not review the address', 'Өтінім авторы мекенжайды тексере алмайды');
