    const b = bk(id); if (!b || !['new', 'confirmed'].includes(b.status)) return T('Отмена невозможна', 'Stornierung nicht möglich', 'Cannot cancel', 'Болдырмау мүмкін емес');
    if (!noteOk(why, 3)) return T('Укажите причину (≥ 3 символов)', 'Grund angeben (≥ 3 Zeichen)', 'Give a reason (≥ 3 characters)', 'Себебін көрсетіңіз (≥ 3 таңба)');
